DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='patient_request_snapshot'; IF definition IS NULL THEN RAISE EXCEPTION 'Patient snapshot missing'; END IF; definition:=replace(definition,'''invoice'',NULL','''invoice'',(SELECT public.get_trip_invoice_snapshot(i.id) FROM public.trip_invoice_documents i WHERE i.request_id=r.id AND public.trip_invoice_access(i.id,false) ORDER BY i.created_at DESC LIMIT 1),''contacts'',public.patient_trip_contacts(r.id)'); EXECUTE definition; END $$;
CREATE FUNCTION public.customer_quote_insert_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' AND NEW.customer_quote_history<>'[]'::jsonb THEN RAISE EXCEPTION 'Quote history is server managed'; ELSIF TG_OP='DELETE' AND OLD.customer_quote_history<>'[]'::jsonb THEN RAISE EXCEPTION 'Confirmed quote history cannot be deleted'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER quote_history_insert_delete_guard BEFORE INSERT OR DELETE ON public.trip_drafts FOR EACH ROW EXECUTE FUNCTION public.customer_quote_insert_guard();
CREATE FUNCTION public.dispatch_contact_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.trip_dispatch_phone:=NULL;NEW.trip_dispatch_phone_designated:=false;ELSIF (NEW.trip_dispatch_phone IS DISTINCT FROM OLD.trip_dispatch_phone OR NEW.trip_dispatch_phone_designated IS DISTINCT FROM OLD.trip_dispatch_phone_designated) AND current_setting('app.dispatch_contact_confirmed',true) IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Trip dispatch contact requires explicit confirmation';END IF;RETURN NEW;END $$;
CREATE TRIGGER dispatch_contact_consent_guard BEFORE INSERT OR UPDATE ON public.provider_network_profiles FOR EACH ROW EXECUTE FUNCTION public.dispatch_contact_guard();
CREATE OR REPLACE FUNCTION public.set_trip_dispatch_contact(_workspace uuid,_phone text,_confirmed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_provider_customer_pricing(_workspace) OR _confirmed IS DISTINCT FROM true OR length(coalesce(_phone,''))>32 THEN RAISE EXCEPTION 'Not available';END IF;PERFORM set_config('app.dispatch_contact_confirmed','true',true); UPDATE public.provider_network_profiles SET trip_dispatch_phone=nullif(trim(_phone),''),trip_dispatch_phone_designated=nullif(trim(_phone),'') IS NOT NULL WHERE workspace_id=_workspace; IF NOT FOUND THEN RAISE EXCEPTION 'Business identity required';END IF; INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) SELECT _workspace,'trip_dispatch_contact_designated',auth.uid(),p.mfn_id,w.mfn_id,jsonb_build_object('designated',nullif(trim(_phone),'') IS NOT NULL) FROM public.user_profiles p,public.workspaces w WHERE p.user_id=auth.uid() AND w.id=_workspace; END $$;
CREATE FUNCTION public.invoice_in_portal_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.trip_invoice_documents;target uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='customer_invoice_in_app_notices' AND enabled) THEN RETURN NEW; END IF;SELECT * INTO i FROM public.trip_invoice_documents WHERE id=NEW.invoice_id; IF NOT EXISTS(SELECT 1 FROM public.ride_requests WHERE id=i.request_id AND NOT is_test) THEN RETURN NEW;END IF; SELECT user_id INTO target FROM public.workspace_members WHERE workspace_id=i.patient_workspace_id AND role='owner' AND NOT is_contractor AND removed_at IS NULL ORDER BY created_at LIMIT 1; IF target IS NOT NULL AND NEW.action IN ('invoice_ready','payment_required','payment_received','payment_failed') THEN INSERT INTO public.notifications(user_id,title,body,link,category) VALUES(target,CASE NEW.action WHEN 'payment_received' THEN 'Payment received' WHEN 'payment_failed' THEN 'Payment failed' ELSE 'Invoice ready — payment required' END,i.mfn_id,'/portal/invoices/'||i.id::text,'payment');END IF;RETURN NEW;END $$;
CREATE TRIGGER invoice_notice_on_event AFTER INSERT ON public.trip_invoice_events FOR EACH ROW EXECUTE FUNCTION public.invoice_in_portal_notice();
COMMENT ON TABLE public.trip_invoice_documents IS 'Immutable customer billing document on existing ride_requests and trip_payments; not a parallel payment ledger. No refund actions or policy. Collection, notifications and sends default off via missing launch flags.';